//! The divergence panel: runs an analysis of how far the open project's code
//! and spec have diverged, showing its steps as they run, then the score and
//! the source and spec trees, where a selected file shows its connections to
//! files on the other side, strongest first.

use std::path::PathBuf;
use std::sync::Arc;

use anyhow::Result;
use gpui_kit::assets::IconName;
use gpui_kit::component::button::{Button, ButtonVariants as _};
use gpui_kit::component::spinner::Spinner;
use gpui_kit::component::{
    ActiveTheme as _, Disableable as _, Icon, Selectable as _, Sizable as _, StyledExt as _,
    h_flex, v_flex,
};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;

use crate::divergence::{
    self, AgentReply, Build, Cancel, Files, Report, RunAgent, Side, Verdict, strength_label,
    tree_rows,
};
use crate::scrollbar;

/// Emitted when the panel is closed.
pub struct CloseDivergence;

/// How a step of the analysis is going.
#[derive(Clone, Debug, PartialEq)]
pub enum StepState {
    Pending,
    Running,
    Done,
    Failed(SharedString),
}

/// The steps of an analysis, in the order they run.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Step {
    Build,
    Code,
    Spec,
}

impl Step {
    const ALL: [Step; 3] = [Step::Build, Step::Code, Step::Spec];

    fn label(self) -> &'static str {
        match self {
            Step::Build => "Building the spec",
            Step::Code => "Analyzing the code",
            Step::Spec => "Analyzing the spec",
        }
    }
}

pub struct DivergenceView {
    project_dir: PathBuf,
    build: Build,
    agent: RunAgent,
    steps: [StepState; 3],
    /// Whether the build failed, so the compiled spec may be out of date.
    build_failed: bool,
    /// Why the files couldn't be listed, if they couldn't.
    error: Option<SharedString>,
    files: Option<Files>,
    report: Option<Report>,
    side: Side,
    selected: Option<String>,
    tree_scroll: ScrollHandle,
    details_scroll: ScrollHandle,
    focus_handle: FocusHandle,
    /// Stops the running analysis's agents.
    cancel: Arc<Cancel>,
    _run: Task<()>,
}

impl EventEmitter<CloseDivergence> for DivergenceView {}

impl Focusable for DivergenceView {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus_handle.clone()
    }
}

impl Drop for DivergenceView {
    fn drop(&mut self) {
        // Closed while it runs, the agents stop.
        self.cancel.cancel();
    }
}

impl DivergenceView {
    /// A panel analyzing the project in `project_dir`, starting straight away.
    pub fn new(project_dir: PathBuf, cx: &mut Context<Self>) -> Self {
        Self::with_runners(project_dir, crate::piton_build::build, divergence::run_agent, cx)
    }

    /// As [`Self::new`], building and running agents with `build` and `agent`.
    pub fn with_runners(
        project_dir: PathBuf,
        build: Build,
        agent: RunAgent,
        cx: &mut Context<Self>,
    ) -> Self {
        let mut this = Self {
            project_dir,
            build,
            agent,
            steps: Step::ALL.map(|_| StepState::Pending),
            build_failed: false,
            error: None,
            files: None,
            report: None,
            side: Side::Source,
            selected: None,
            tree_scroll: ScrollHandle::new(),
            details_scroll: ScrollHandle::new(),
            focus_handle: cx.focus_handle(),
            cancel: Arc::default(),
            _run: Task::ready(()),
        };
        this.analyze(cx);
        this
    }

    #[cfg(test)]
    pub fn report(&self) -> Option<&Report> {
        self.report.as_ref()
    }

    #[cfg(test)]
    pub fn side(&self) -> Side {
        self.side
    }

    #[cfg(test)]
    pub fn selected(&self) -> Option<&str> {
        self.selected.as_deref()
    }

    #[cfg(test)]
    pub fn step(&self, step: Step) -> &StepState {
        &self.steps[step as usize]
    }

    fn running(&self) -> bool {
        self.steps
            .iter()
            .any(|state| matches!(state, StepState::Running | StepState::Pending))
            && self.error.is_none()
    }

    fn set_step(&mut self, step: Step, state: StepState, cx: &mut Context<Self>) {
        self.steps[step as usize] = state;
        cx.notify();
    }

    /// Starts a fresh analysis: builds the spec, then runs both agents at
    /// once, and merges what they found.
    pub fn analyze(&mut self, cx: &mut Context<Self>) {
        self.cancel.cancel();
        self.cancel = Arc::default();
        self.steps = Step::ALL.map(|_| StepState::Pending);
        self.build_failed = false;
        self.error = None;
        self.files = None;
        self.report = None;
        self.selected = None;
        self.side = Side::Source;
        cx.notify();

        let (project_dir, build, agent, cancel) = (
            self.project_dir.clone(),
            self.build,
            self.agent,
            self.cancel.clone(),
        );
        self._run = cx.spawn(async move |this, cx| {
            let listed = cx
                .background_spawn({
                    let project_dir = project_dir.clone();
                    async move { divergence::list_files(&project_dir) }
                })
                .await;
            let files = match listed {
                Ok(files) => files,
                Err(err) => {
                    this.update(cx, |this, cx| {
                        this.error = Some(format!("{err:#}").into());
                        cx.notify();
                    })
                    .ok();
                    return;
                }
            };

            this.update(cx, |this, cx| {
                this.files = Some(files.clone());
                this.set_step(Step::Build, StepState::Running, cx)
            })
            .ok();
            let built = cx
                .background_spawn({
                    let project_dir = project_dir.clone();
                    async move { build(&project_dir) }
                })
                .await;
            let build_failed = !matches!(built, Ok(ref outcome) if outcome.success);
            let updated = this.update(cx, |this, cx| {
                this.build_failed = build_failed;
                this.set_step(Step::Build, StepState::Done, cx);
                this.set_step(Step::Code, StepState::Running, cx);
                this.set_step(Step::Spec, StepState::Running, cx);
            });
            if updated.is_err() {
                return;
            }

            let run = |side: Side| {
                let (project_dir, cancel, prompt) = (
                    project_dir.clone(),
                    cancel.clone(),
                    divergence::prompt(side, &files),
                );
                cx.background_spawn(async move {
                    let reply = agent(&project_dir, &prompt, &cancel)?;
                    divergence::parse_reply(&reply)
                })
            };
            let (code, spec) = (run(Side::Source), run(Side::Spec));
            let (code, spec): (Result<AgentReply>, Result<AgentReply>) =
                futures::join!(code, spec);

            this.update(cx, |this, cx| {
                let state = |result: &Result<AgentReply>| match result {
                    Ok(_) => StepState::Done,
                    Err(err) => StepState::Failed(format!("{err:#}").into()),
                };
                this.steps[Step::Code as usize] = state(&code);
                this.steps[Step::Spec as usize] = state(&spec);
                if code.is_ok() || spec.is_ok() {
                    let report = divergence::merge(
                        &files.sources,
                        &files.specs,
                        code.as_ref().ok(),
                        spec.as_ref().ok(),
                    );
                    // The source file that diverges most is selected.
                    this.selected = report
                        .sources
                        .iter()
                        .filter_map(|file| Some((file.divergence?, &file.path)))
                        .max_by(|a, b| a.0.total_cmp(&b.0))
                        .map(|(_, path)| path.clone());
                    this.report = Some(report);
                }
                cx.notify();
            })
            .ok();
        });
    }

    fn close(&mut self, cx: &mut Context<Self>) {
        self.cancel.cancel();
        cx.emit(CloseDivergence);
    }

    pub fn set_side(&mut self, side: Side, cx: &mut Context<Self>) {
        if self.side != side {
            self.side = side;
            self.selected = None;
            self.tree_scroll.set_offset(point(px(0.), px(0.)));
            cx.notify();
        }
    }

    pub fn select(&mut self, path: String, cx: &mut Context<Self>) {
        self.selected = Some(path);
        self.details_scroll.set_offset(point(px(0.), px(0.)));
        cx.notify();
    }

    /// Follows a connection to `path` on the other side: that tree, with the
    /// file selected and scrolled into view.
    pub fn follow(&mut self, path: String, cx: &mut Context<Self>) {
        self.side = self.side.other();
        let row = self
            .files
            .as_ref()
            .map(|_| self.tree_paths())
            .and_then(|paths| {
                tree_rows(&paths)
                    .iter()
                    .position(|row| row.file.as_deref() == Some(path.as_str()))
            });
        self.select(path, cx);
        if let Some(row) = row {
            self.tree_scroll.scroll_to_item(row);
        }
    }

    fn tree_paths(&self) -> Vec<String> {
        self.report
            .as_ref()
            .map(|report| {
                report
                    .files(self.side)
                    .iter()
                    .map(|file| file.path.clone())
                    .collect()
            })
            .unwrap_or_default()
    }

    fn verdict_color(percent: u32, cx: &App) -> Hsla {
        let theme = cx.theme();
        match Verdict::of(percent) {
            Verdict::Aligned => theme.success,
            Verdict::Drifting => theme.warning,
            Verdict::Diverged => theme.danger,
        }
    }

    fn render_header(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        let score = self.report.as_ref().and_then(Report::score);
        h_flex()
            .flex_none()
            .gap_3()
            .pl_4()
            .pr_1()
            .py_2()
            .border_b_1()
            .border_color(theme.border)
            .child(
                Icon::new(IconName::GitCompareArrows)
                    .small()
                    .text_color(theme.muted_foreground),
            )
            .child(div().font_semibold().child("Divergence"))
            .when_some(score, |header, score| {
                let color = Self::verdict_color(score, cx);
                header.child(
                    h_flex()
                        .id("divergence-score")
                        .gap_2()
                        .items_baseline()
                        .child(
                            div()
                                .text_2xl()
                                .font_bold()
                                .text_color(color)
                                .child(format!("{score}%")),
                        )
                        .child(
                            div()
                                .text_sm()
                                .text_color(color)
                                .child(Verdict::of(score).label()),
                        ),
                )
            })
            .child(div().flex_1())
            .child(
                Button::new("divergence-analyze-again")
                    .ghost()
                    .small()
                    .icon(IconName::RefreshCw)
                    .label("Analyze again")
                    .disabled(self.running())
                    .on_click(cx.listener(|this, _, _, cx| this.analyze(cx))),
            )
            .child(
                Button::new("divergence-close")
                    .ghost()
                    .small()
                    .icon(IconName::X)
                    .tooltip("Close, stopping any analysis still running")
                    .on_click(cx.listener(|this, _, _, cx| this.close(cx))),
            )
    }

    fn render_steps(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        v_flex()
            .id("divergence-steps")
            .gap_2()
            .p_6()
            .children(self.error.clone().map(|error| {
                div()
                    .text_color(theme.danger)
                    .child(format!("Couldn't analyze the project: {error}"))
            }))
            .children(Step::ALL.into_iter().map(|step| {
                let state = &self.steps[step as usize];
                let icon: AnyElement = match state {
                    StepState::Pending => div().size_4().into_any_element(),
                    StepState::Running => Spinner::new().small().into_any_element(),
                    StepState::Done => Icon::new(IconName::Check)
                        .small()
                        .text_color(theme.success)
                        .into_any_element(),
                    StepState::Failed(_) => Icon::new(IconName::X)
                        .small()
                        .text_color(theme.danger)
                        .into_any_element(),
                };
                v_flex()
                    .gap_0p5()
                    .child(
                        h_flex()
                            .gap_2()
                            .child(icon)
                            .child(div().when(*state == StepState::Pending, |label| {
                                label.text_color(theme.muted_foreground)
                            }).child(step.label())),
                    )
                    .when_some(
                        match state {
                            StepState::Failed(why) => Some(why.clone()),
                            _ => None,
                        },
                        |row, why| {
                            row.child(div().pl_6().text_sm().text_color(theme.danger).child(why))
                        },
                    )
            }))
    }

    /// Notes about the results: a failed build, a side cut short, or an agent
    /// that failed.
    fn notes(&self) -> Vec<String> {
        let mut notes = Vec::new();
        if self.build_failed {
            notes.push("piton build failed, so the compiled spec may be out of date.".into());
        }
        if let Some(files) = &self.files {
            if files.sources_truncated {
                notes.push(format!(
                    "Only the first {} source files were analyzed.",
                    divergence::MAX_FILES
                ));
            }
            if files.specs_truncated {
                notes.push(format!(
                    "Only the first {} spec files were analyzed.",
                    divergence::MAX_FILES
                ));
            }
        }
        for step in [Step::Code, Step::Spec] {
            if let StepState::Failed(why) = &self.steps[step as usize] {
                notes.push(format!("{} failed: {why}", step.label()));
            }
        }
        notes
    }

    fn render_tree(&self, report: &Report, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme();
        let files = report.files(self.side);
        let paths: Vec<String> = files.iter().map(|file| file.path.clone()).collect();
        let rows = tree_rows(&paths).into_iter().enumerate().map(|(ix, row)| {
            let indent = px(12. + 14. * row.depth as f32);
            let Some(path) = row.file else {
                return h_flex()
                    .id(("divergence-folder", ix))
                    .gap_1p5()
                    .pl(indent)
                    .py_0p5()
                    .text_color(theme.muted_foreground)
                    .child(Icon::new(IconName::FolderOpen).xsmall())
                    .child(row.name)
                    .into_any_element();
            };
            let divergence = files
                .iter()
                .find(|file| file.path == path)
                .and_then(|file| file.divergence);
            let selected = self.selected.as_deref() == Some(path.as_str());
            let meter = match divergence {
                Some(value) => {
                    let percent = (value * 100.).round() as u32;
                    let color = Self::verdict_color(percent, cx);
                    h_flex()
                        .flex_none()
                        .gap_2()
                        .child(
                            div()
                                .w(px(48.))
                                .h(px(4.))
                                .rounded_full()
                                .bg(theme.muted)
                                .child(div().h_full().rounded_full().bg(color).w(relative(value))),
                        )
                        .child(
                            div()
                                .w(px(36.))
                                .text_right()
                                .text_xs()
                                .text_color(theme.muted_foreground)
                                .child(format!("{percent}%")),
                        )
                        .into_any_element()
                }
                None => div()
                    .flex_none()
                    .text_xs()
                    .text_color(theme.muted_foreground)
                    .child("Not analyzed")
                    .into_any_element(),
            };
            let target = path.clone();
            let row = h_flex()
                .id(("divergence-file", ix))
                .gap_2()
                .pl(indent)
                .pr_2()
                .py_0p5()
                .cursor_pointer()
                .when(selected, |row| row.bg(theme.list_active))
                .when(!selected, |row| row.hover(|row| row.bg(theme.list_hover)))
                .on_click(cx.listener(move |this, _, _, cx| this.select(target.clone(), cx)))
                .child(Icon::new(IconName::File).xsmall().text_color(theme.muted_foreground))
                .child(div().flex_1().min_w_0().truncate().child(row.name))
                .child(meter);
            // Lets UI tests find the row; inert in normal builds.
            gpui_kit::TestSupportExt::test_support(row).into_any_element()
        });
        let list = v_flex()
            .id("divergence-tree")
            .size_full()
            .overflow_y_scroll()
            .track_scroll(&self.tree_scroll)
            .py_1()
            .children(rows);
        scrollbar::with_scrollbar("divergence-tree", &self.tree_scroll, list, true, None, cx)
    }

    fn render_details(&self, report: &Report, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme();
        let Some(path) = &self.selected else {
            return div()
                .p_6()
                .text_color(theme.muted_foreground)
                .child("Select a file to see what it's connected to.")
                .into_any_element();
        };
        let file = report.files(self.side).iter().find(|file| &file.path == path);
        let divergence = file.and_then(|file| file.divergence);
        let other = self.side.other();
        let connections = report.connections_of(self.side, path);
        let rows = connections.iter().enumerate().map(|(ix, connection)| {
            let target = connection.end(other).to_string();
            let strength = connection.strength;
            let row = v_flex()
                .id(("divergence-connection", ix))
                .gap_1()
                .px_3()
                .py_2()
                .rounded(theme.radius)
                .border_1()
                .border_color(theme.border)
                .cursor_pointer()
                .hover(|row| row.bg(theme.list_hover))
                .on_click(cx.listener(move |this, _, _, cx| this.follow(target.clone(), cx)))
                .child(
                    h_flex()
                        .gap_2()
                        .child(
                            div()
                                .flex_1()
                                .min_w_0()
                                .truncate()
                                .font_family(theme.mono_font_family.clone())
                                .child(connection.end(other).to_string()),
                        )
                        .child(
                            div()
                                .flex_none()
                                .text_sm()
                                .text_color(theme.muted_foreground)
                                .child(format!(
                                    "{} · {}%",
                                    strength_label(strength),
                                    (strength * 100.).round() as u32
                                )),
                        ),
                )
                .child(
                    div()
                        .w_full()
                        .h(px(6.))
                        .rounded_full()
                        .bg(theme.muted)
                        .child(
                            div()
                                .h_full()
                                .rounded_full()
                                .bg(theme.primary.opacity(0.35 + 0.65 * strength))
                                .w(relative(strength)),
                        ),
                )
                .children(
                    (!connection.notes.is_empty()).then(|| {
                        div()
                            .text_sm()
                            .text_color(theme.muted_foreground)
                            .child(connection.notes.join(" · "))
                    }),
                );
            // Lets UI tests find the connection; inert in normal builds.
            gpui_kit::TestSupportExt::test_support(row)
        });
        let body = v_flex()
            .id("divergence-details")
            .size_full()
            .overflow_y_scroll()
            .track_scroll(&self.details_scroll)
            .gap_3()
            .p_4()
            .child(
                div()
                    .font_semibold()
                    .font_family(theme.mono_font_family.clone())
                    .child(path.clone()),
            )
            .child(div().text_sm().text_color(theme.muted_foreground).child(match divergence {
                Some(value) => format!("Diverges {}%", (value * 100.).round() as u32),
                None => "Not analyzed".to_string(),
            }))
            .children(
                file.map(|file| file.summary.clone())
                    .filter(|summary| !summary.is_empty())
                    .map(|summary| div().child(summary)),
            )
            .child(div().pt_2().font_medium().child(match connections.len() {
                0 => format!("No connected {} files", other.label().to_lowercase()),
                1 => format!("1 connected {} file", other.label().to_lowercase()),
                n => format!("{n} connected {} files", other.label().to_lowercase()),
            }))
            .children(rows);
        scrollbar::with_scrollbar("divergence-details", &self.details_scroll, body, true, None, cx)
    }

    fn render_results(&self, report: &Report, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        let side_button = |id: &'static str, side: Side| {
            Button::new(id)
                .small()
                .label(side.label())
                .selected(self.side == side)
                .on_click(cx.listener(move |this, _, _, cx| this.set_side(side, cx)))
        };
        let notes = self.notes();
        v_flex()
            .size_full()
            .children((!notes.is_empty()).then(|| {
                v_flex()
                    .flex_none()
                    .px_4()
                    .py_2()
                    .border_b_1()
                    .border_color(theme.border)
                    .text_sm()
                    .text_color(theme.warning)
                    .children(notes)
            }))
            .child(
                h_flex()
                    .flex_1()
                    .min_h_0()
                    .child(
                        v_flex()
                            .w(relative(0.4))
                            .h_full()
                            .border_r_1()
                            .border_color(theme.border)
                            .child(
                                h_flex()
                                    .flex_none()
                                    .gap_1()
                                    .p_2()
                                    .border_b_1()
                                    .border_color(theme.border)
                                    .child(side_button("divergence-side-source", Side::Source))
                                    .child(side_button("divergence-side-spec", Side::Spec)),
                            )
                            .child(div().flex_1().min_h_0().child(self.render_tree(report, cx))),
                    )
                    .child(div().flex_1().min_w_0().h_full().child(self.render_details(report, cx))),
            )
    }
}

impl Render for DivergenceView {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let body = match (&self.report, self.running()) {
            (Some(report), false) => self.render_results(&report.clone(), cx).into_any_element(),
            _ => self.render_steps(cx).into_any_element(),
        };
        let view = v_flex()
            .id("divergence")
            .track_focus(&self.focus_handle)
            .size_full()
            .bg(cx.theme().background)
            .child(self.render_header(cx))
            .child(div().flex_1().min_h_0().child(body));
        // Lets UI tests find the view; inert in normal builds.
        gpui_kit::TestSupportExt::test_support(view)
    }
}

tool_use_result.content:
//! The divergence panel: runs an analysis of how far the open project's code
//! and spec have diverged, showing its steps as they run, then the score and
//! the source and spec trees, where a selected file shows its connections to
//! files on the other side, strongest first.

use std::path::PathBuf;
use std::sync::Arc;

use anyhow::Result;
use gpui_kit::assets::IconName;
use gpui_kit::component::button::{Button, ButtonVariants as _};
use gpui_kit::component::spinner::Spinner;
use gpui_kit::component::{
    ActiveTheme as _, Disableable as _, Icon, Selectable as _, Sizable as _, StyledExt as _,
    h_flex, v_flex,
};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;

use crate::divergence::{
    self, AgentReply, Build, Cancel, Files, Report, RunAgent, Side, Verdict, strength_label,
    tree_rows,
};
use crate::scrollbar;

/// Emitted when the panel is closed.
pub struct CloseDivergence;

/// How a step of the analysis is going.
#[derive(Clone, Debug, PartialEq)]
pub enum StepState {
    Pending,
    Running,
    Done,
    Failed(SharedString),
}

/// The steps of an analysis, in the order they run.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Step {
    Build,
    Code,
    Spec,
}

impl Step {
    const ALL: [Step; 3] = [Step::Build, Step::Code, Step::Spec];

    fn label(self) -> &'static str {
        match self {
            Step::Build => "Building the spec",
            Step::Code => "Analyzing the code",
            Step::Spec => "Analyzing the spec",
        }
    }
}

pub struct DivergenceView {
    project_dir: PathBuf,
    build: Build,
    agent: RunAgent,
    steps: [StepState; 3],
    /// Whether the build failed, so the compiled spec may be out of date.
    build_failed: bool,
    /// Why the files couldn't be listed, if they couldn't.
    error: Option<SharedString>,
    files: Option<Files>,
    report: Option<Report>,
    side: Side,
    selected: Option<String>,
    tree_scroll: ScrollHandle,
    details_scroll: ScrollHandle,
    focus_handle: FocusHandle,
    /// Stops the running analysis's agents.
    cancel: Arc<Cancel>,
    _run: Task<()>,
}

impl EventEmitter<CloseDivergence> for DivergenceView {}

impl Focusable for DivergenceView {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus_handle.clone()
    }
}

impl Drop for DivergenceView {
    fn drop(&mut self) {
        // Closed while it runs, the agents stop.
        self.cancel.cancel();
    }
}

impl DivergenceView {
    /// A panel analyzing the project in `project_dir`, starting straight away.
    pub fn new(project_dir: PathBuf, cx: &mut Context<Self>) -> Self {
        Self::with_runners(project_dir, crate::piton_build::build, divergence::run_agent, cx)
    }

    /// As [`Self::new`], building and running agents with `build` and `agent`.
    pub fn with_runners(
        project_dir: PathBuf,
        build: Build,
        agent: RunAgent,
        cx: &mut Context<Self>,
    ) -> Self {
        let mut this = Self {
            project_dir,
            build,
            agent,
            steps: Step::ALL.map(|_| StepState::Pending),
            build_failed: false,
            error: None,
            files: None,
            report: None,
            side: Side::Source,
            selected: None,
            tree_scroll: ScrollHandle::new(),
            details_scroll: ScrollHandle::new(),
            focus_handle: cx.focus_handle(),
            cancel: Arc::default(),
            _run: Task::ready(()),
        };
        this.analyze(cx);
        this
    }

    #[cfg(test)]
    pub fn report(&self) -> Option<&Report> {
        self.report.as_ref()
    }

    #[cfg(test)]
    pub fn side(&self) -> Side {
        self.side
    }

    #[cfg(test)]
    pub fn selected(&self) -> Option<&str> {
        self.selected.as_deref()
    }

    #[cfg(test)]
    pub fn step(&self, step: Step) -> &StepState {
        &self.steps[step as usize]
    }

    fn running(&self) -> bool {
        self.steps
            .iter()
            .any(|state| matches!(state, StepState::Running | StepState::Pending))
            && self.error.is_none()
    }

    fn set_step(&mut self, step: Step, state: StepState, cx: &mut Context<Self>) {
        self.steps[step as usize] = state;
        cx.notify();
    }

    /// Starts a fresh analysis: builds the spec, then runs both agents at
    /// once, and merges what they found.
    pub fn analyze(&mut self, cx: &mut Context<Self>) {
        self.cancel.cancel();
        self.cancel = Arc::default();
        self.steps = Step::ALL.map(|_| StepState::Pending);
        self.build_failed = false;
        self.error = None;
        self.files = None;
        self.report = None;
        self.selected = None;
        self.side = Side::Source;
        cx.notify();

        let (project_dir, build, agent, cancel) = (
            self.project_dir.clone(),
            self.build,
            self.agent,
            self.cancel.clone(),
        );
        self._run = cx.spawn(async move |this, cx| {
            let listed = cx
                .background_spawn({
                    let project_dir = project_dir.clone();
                    async move { divergence::list_files(&project_dir) }
                })
                .await;
            let files = match listed {
                Ok(files) => files,
                Err(err) => {
                    this.update(cx, |this, cx| {
                        this.error = Some(format!("{err:#}").into());
                        cx.notify();
                    })
                    .ok();
                    return;
                }
            };

            this.update(cx, |this, cx| {
                this.files = Some(files.clone());
                this.set_step(Step::Build, StepState::Running, cx)
            })
            .ok();
            let built = cx
                .background_spawn({
                    let project_dir = project_dir.clone();
                    async move { build(&project_dir) }
                })
                .await;
            let build_failed = !matches!(built, Ok(ref outcome) if outcome.success);
            let updated = this.update(cx, |this, cx| {
                this.build_failed = build_failed;
                this.set_step(Step::Build, StepState::Done, cx);
                this.set_step(Step::Code, StepState::Running, cx);
                this.set_step(Step::Spec, StepState::Running, cx);
            });
            if updated.is_err() {
                return;
            }

            let run = |side: Side| {
                let (project_dir, cancel, prompt) = (
                    project_dir.clone(),
                    cancel.clone(),
                    divergence::prompt(side, &files),
                );
                cx.background_spawn(async move {
                    let reply = agent(&project_dir, &prompt, &cancel)?;
                    divergence::parse_reply(&reply)
                })
            };
            let (code, spec) = (run(Side::Source), run(Side::Spec));
            let (code, spec): (Result<AgentReply>, Result<AgentReply>) =
                futures::join!(code, spec);

            this.update(cx, |this, cx| {
                let state = |result: &Result<AgentReply>| match result {
                    Ok(_) => StepState::Done,
                    Err(err) => StepState::Failed(format!("{err:#}").into()),
                };
                this.steps[Step::Code as usize] = state(&code);
                this.steps[Step::Spec as usize] = state(&spec);
                if code.is_ok() || spec.is_ok() {
                    let report = divergence::merge(
                        &files.sources,
                        &files.specs,
                        code.as_ref().ok(),
                        spec.as_ref().ok(),
                    );
                    // The source file that diverges most is selected.
                    this.selected = report
                        .sources
                        .iter()
                        .filter_map(|file| Some((file.divergence?, &file.path)))
                        .max_by(|a, b| a.0.total_cmp(&b.0))
                        .map(|(_, path)| path.clone());
                    this.report = Some(report);
                }
                cx.notify();
            })
            .ok();
        });
    }

    fn close(&mut self, cx: &mut Context<Self>) {
        self.cancel.cancel();
        cx.emit(CloseDivergence);
    }

    pub fn set_side(&mut self, side: Side, cx: &mut Context<Self>) {
        if self.side != side {
            self.side = side;
            self.selected = None;
            self.tree_scroll.set_offset(point(px(0.), px(0.)));
            cx.notify();
        }
    }

    pub fn select(&mut self, path: String, cx: &mut Context<Self>) {
        self.selected = Some(path);
        self.details_scroll.set_offset(point(px(0.), px(0.)));
        cx.notify();
    }

    /// Follows a connection to `path` on the other side: that tree, with the
    /// file selected and scrolled into view.
    pub fn follow(&mut self, path: String, cx: &mut Context<Self>) {
        self.side = self.side.other();
        let row = self
            .files
            .as_ref()
            .map(|_| self.tree_paths())
            .and_then(|paths| {
                tree_rows(&paths)
                    .iter()
                    .position(|row| row.file.as_deref() == Some(path.as_str()))
            });
        self.select(path, cx);
        if let Some(row) = row {
            self.tree_scroll.scroll_to_item(row);
        }
    }

    fn tree_paths(&self) -> Vec<String> {
        self.report
            .as_ref()
            .map(|report| {
                report
                    .files(self.side)
                    .iter()
                    .map(|file| file.path.clone())
                    .collect()
            })
            .unwrap_or_default()
    }

    fn verdict_color(percent: u32, cx: &App) -> Hsla {
        let theme = cx.theme();
        match Verdict::of(percent) {
            Verdict::Aligned => theme.success,
            Verdict::Drifting => theme.warning,
            Verdict::Diverged => theme.danger,
        }
    }

    fn render_header(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        let score = self.report.as_ref().and_then(Report::score);
        h_flex()
            .flex_none()
            .gap_3()
            .pl_4()
            .pr_1()
            .py_2()
            .border_b_1()
            .border_color(theme.border)
            .child(
                Icon::new(IconName::GitCompareArrows)
                    .small()
                    .text_color(theme.muted_foreground),
            )
            .child(div().font_semibold().child("Divergence"))
            .when_some(score, |header, score| {
                let color = Self::verdict_color(score, cx);
                header.child(
                    h_flex()
                        .id("divergence-score")
                        .gap_2()
                        .items_baseline()
                        .child(
                            div()
                                .text_2xl()
                                .font_bold()
                                .text_color(color)
                                .child(format!("{score}%")),
                        )
                        .child(
                            div()
                                .text_sm()
                                .text_color(color)
                                .child(Verdict::of(score).label()),
                        ),
                )
            })
            .child(div().flex_1())
            .child(
                Button::new("divergence-analyze-again")
                    .ghost()
                    .small()
                    .icon(IconName::RefreshCw)
                    .label("Analyze again")
                    .disabled(self.running())
                    .on_click(cx.listener(|this, _, _, cx| this.analyze(cx))),
            )
            .child(
                Button::new("divergence-close")
                    .ghost()
                    .small()
                    .icon(IconName::X)
                    .tooltip("Close, stopping any analysis still running")
                    .on_click(cx.listener(|this, _, _, cx| this.close(cx))),
            )
    }

    fn render_steps(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        v_flex()
            .id("divergence-steps")
            .gap_2()
            .p_6()
            .children(self.error.clone().map(|error| {
                div()
                    .text_color(theme.danger)
                    .child(format!("Couldn't analyze the project: {error}"))
            }))
            .children(Step::ALL.into_iter().map(|step| {
                let state = &self.steps[step as usize];
                let icon: AnyElement = match state {
                    StepState::Pending => div().size_4().into_any_element(),
                    StepState::Running => Spinner::new().small().into_any_element(),
                    StepState::Done => Icon::new(IconName::Check)
                        .small()
                        .text_color(theme.success)
                        .into_any_element(),
                    StepState::Failed(_) => Icon::new(IconName::X)
                        .small()
                        .text_color(theme.danger)
                        .into_any_element(),
                };
                v_flex()
                    .gap_0p5()
                    .child(
                        h_flex()
                            .gap_2()
                            .child(icon)
                            .child(div().when(*state == StepState::Pending, |label| {
                                label.text_color(theme.muted_foreground)
                            }).child(step.label())),
                    )
                    .when_some(
                        match state {
                            StepState::Failed(why) => Some(why.clone()),
                            _ => None,
                        },
                        |row, why| {
                            row.child(div().pl_6().text_sm().text_color(theme.danger).child(why))
                        },
                    )
            }))
    }

    /// Notes about the results: a failed build, a side cut short, or an agent
    /// that failed.
    fn notes(&self) -> Vec<String> {
        let mut notes = Vec::new();
        if self.build_failed {
            notes.push("piton build failed, so the compiled spec may be out of date.".into());
        }
        if let Some(files) = &self.files {
            if files.sources_truncated {
                notes.push(format!(
                    "Only the first {} source files were analyzed.",
                    divergence::MAX_FILES
                ));
            }
            if files.specs_truncated {
                notes.push(format!(
                    "Only the first {} spec files were analyzed.",
                    divergence::MAX_FILES
                ));
            }
        }
        for step in [Step::Code, Step::Spec] {
            if let StepState::Failed(why) = &self.steps[step as usize] {
                notes.push(format!("{} failed: {why}", step.label()));
            }
        }
        notes
    }

    fn render_tree(&self, report: &Report, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme();
        let files = report.files(self.side);
        let paths: Vec<String> = files.iter().map(|file| file.path.clone()).collect();
        let rows = tree_rows(&paths).into_iter().enumerate().map(|(ix, row)| {
            let indent = px(12. + 14. * row.depth as f32);
            let Some(path) = row.file else {
                return h_flex()
                    .id(("divergence-folder", ix))
                    .gap_1p5()
                    .pl(indent)
                    .py_0p5()
                    .text_color(theme.muted_foreground)
                    .child(Icon::new(IconName::FolderOpen).xsmall())
                    .child(row.name)
                    .into_any_element();
            };
            let divergence = files
                .iter()
                .find(|file| file.path == path)
                .and_then(|file| file.divergence);
            let selected = self.selected.as_deref() == Some(path.as_str());
            let meter = match divergence {
                Some(value) => {
                    let percent = (value * 100.).round() as u32;
                    let color = Self::verdict_color(percent, cx);
                    h_flex()
                        .flex_none()
                        .gap_2()
                        .child(
                            div()
                                .w(px(48.))
                                .h(px(4.))
                                .rounded_full()
                                .bg(theme.muted)
                                .child(div().h_full().rounded_full().bg(color).w(relative(value))),
                        )
                        .child(
                            div()
                                .w(px(36.))
                                .text_right()
                                .text_xs()
                                .text_color(theme.muted_foreground)
                                .child(format!("{percent}%")),
                        )
                        .into_any_element()
                }
                None => div()
                    .flex_none()
                    .text_xs()
                    .text_color(theme.muted_foreground)
                    .child("Not analyzed")
                    .into_any_element(),
            };
            let target = path.clone();
            let row = h_flex()
                .id(("divergence-file", ix))
                .gap_2()
                .pl(indent)
                .pr_2()
                .py_0p5()
                .cursor_pointer()
                .when(selected, |row| row.bg(theme.list_active))
                .when(!selected, |row| row.hover(|row| row.bg(theme.list_hover)))
                .on_click(cx.listener(move |this, _, _, cx| this.select(target.clone(), cx)))
                .child(Icon::new(IconName::File).xsmall().text_color(theme.muted_foreground))
                .child(div().flex_1().min_w_0().truncate().child(row.name))
                .child(meter);
            // Lets UI tests find the row; inert in normal builds.
            gpui_kit::TestSupportExt::test_support(row).into_any_element()
        });
        let list = v_flex()
            .id("divergence-tree")
            .size_full()
            .overflow_y_scroll()
            .track_scroll(&self.tree_scroll)
            .py_1()
            .children(rows);
        scrollbar::with_scrollbar("divergence-tree", &self.tree_scroll, list, true, None, cx)
    }

    fn render_details(&self, report: &Report, cx: &mut Context<Self>) -> AnyElement {
        let theme = cx.theme();
        let Some(path) = &self.selected else {
            return div()
                .p_6()
                .text_color(theme.muted_foreground)
                .child("Select a file to see what it's connected to.")
                .into_any_element();
        };
        let file = report.files(self.side).iter().find(|file| &file.path == path);
        let divergence = file.and_then(|file| file.divergence);
        let other = self.side.other();
        let connections = report.connections_of(self.side, path);
        let rows = connections.iter().enumerate().map(|(ix, connection)| {
            let target = connection.end(other).to_string();
            let strength = connection.strength;
            let row = v_flex()
                .id(("divergence-connection", ix))
                .gap_1()
                .px_3()
                .py_2()
                .rounded(theme.radius)
                .border_1()
                .border_color(theme.border)
                .cursor_pointer()
                .hover(|row| row.bg(theme.list_hover))
                .on_click(cx.listener(move |this, _, _, cx| this.follow(target.clone(), cx)))
                .child(
                    h_flex()
                        .gap_2()
                        .child(
                            div()
                                .flex_1()
                                .min_w_0()
                                .truncate()
                                .font_family(theme.mono_font_family.clone())
                                .child(connection.end(other).to_string()),
                        )
                        .child(
                            div()
                                .flex_none()
                                .text_sm()
                                .text_color(theme.muted_foreground)
                                .child(format!(
                                    "{} · {}%",
                                    strength_label(strength),
                                    (strength * 100.).round() as u32
                                )),
                        ),
                )
                .child(
                    div()
                        .w_full()
                        .h(px(6.))
                        .rounded_full()
                        .bg(theme.muted)
                        .child(
                            div()
                                .h_full()
                                .rounded_full()
                                .bg(theme.primary.opacity(0.35 + 0.65 * strength))
                                .w(relative(strength)),
                        ),
                )
                .children(
                    (!connection.notes.is_empty()).then(|| {
                        div()
                            .text_sm()
                            .text_color(theme.muted_foreground)
                            .child(connection.notes.join(" · "))
                    }),
                );
            // Lets UI tests find the connection; inert in normal builds.
            gpui_kit::TestSupportExt::test_support(row)
        });
        let body = v_flex()
            .id("divergence-details")
            .size_full()
            .overflow_y_scroll()
            .track_scroll(&self.details_scroll)
            .gap_3()
            .p_4()
            .child(
                div()
                    .font_semibold()
                    .font_family(theme.mono_font_family.clone())
                    .child(path.clone()),
            )
            .child(div().text_sm().text_color(theme.muted_foreground).child(match divergence {
                Some(value) => format!("Diverges {}%", (value * 100.).round() as u32),
                None => "Not analyzed".to_string(),
            }))
            .children(
                file.map(|file| file.summary.clone())
                    .filter(|summary| !summary.is_empty())
                    .map(|summary| div().child(summary)),
            )
            .child(div().pt_2().font_medium().child(match connections.len() {
                0 => format!("No connected {} files", other.label().to_lowercase()),
                1 => format!("1 connected {} file", other.label().to_lowercase()),
                n => format!("{n} connected {} files", other.label().to_lowercase()),
            }))
            .children(rows);
        scrollbar::with_scrollbar("divergence-details", &self.details_scroll, body, true, None, cx)
    }

    fn render_results(&self, report: &Report, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        let side_button = |id: &'static str, side: Side| {
            Button::new(id)
                .small()
                .label(side.label())
                .selected(self.side == side)
                .on_click(cx.listener(move |this, _, _, cx| this.set_side(side, cx)))
        };
        let notes = self.notes();
        v_flex()
            .size_full()
            .children((!notes.is_empty()).then(|| {
                v_flex()
                    .flex_none()
                    .px_4()
                    .py_2()
                    .border_b_1()
                    .border_color(theme.border)
                    .text_sm()
                    .text_color(theme.warning)
                    .children(notes)
            }))
            .child(
                h_flex()
                    .flex_1()
                    .min_h_0()
                    .child(
                        v_flex()
                            .w(relative(0.4))
                            .h_full()
                            .border_r_1()
                            .border_color(theme.border)
                            .child(
                                h_flex()
                                    .flex_none()
                                    .gap_1()
                                    .p_2()
                                    .border_b_1()
                                    .border_color(theme.border)
                                    .child(side_button("divergence-side-source", Side::Source))
                                    .child(side_button("divergence-side-spec", Side::Spec)),
                            )
                            .child(div().flex_1().min_h_0().child(self.render_tree(report, cx))),
                    )
                    .child(div().flex_1().min_w_0().h_full().child(self.render_details(report, cx))),
            )
    }
}

impl Render for DivergenceView {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let body = match (&self.report, self.running()) {
            (Some(report), false) => self.render_results(&report.clone(), cx).into_any_element(),
            _ => self.render_steps(cx).into_any_element(),
        };
        let view = v_flex()
            .id("divergence")
            .track_focus(&self.focus_handle)
            .size_full()
            .bg(cx.theme().background)
            .child(self.render_header(cx))
            .child(div().flex_1().min_h_0().child(body));
        // Lets UI tests find the view; inert in normal builds.
        gpui_kit::TestSupportExt::test_support(view)
    }
}

