        let mut view = None;
        let window = cx.add_window(|window, cx| {
            let divergence = cx.new(|cx| {
                DivergenceView::with_runners(
                    PathBuf::from(env!("CARGO_MANIFEST_DIR")),
                    built,
                    run,
                    cx,
                )
            });
            view = Some(divergence.clone());
            Root::new(divergence, window, cx)
        });
        (view.unwrap(), window.into())
    }

